head.script:
            // jQuery 조회 순서(받은 선택자 → 없으면 mf_ 접두사). 2026-11
scwin.__getJq = function(q) {
    var j = $(q); if (j.length) return j;
    var P = 'mf_', t = q.trim(), r = t.slice(1);
    if (r.slice(0, 2) === 'G_') r = 'G_' + P + r.slice(2); else if (r.slice(0, P.length) !== P) r = P + r;
    return $(t.slice(0, 1) + r);
};
scwin.createWindowTest = function(title, id){
                wc1.createWindow( title , "" , "windowContainer_processMsgFrame_scroll_WESD-1052_(WSQ-5025)_sub.xml" , "windowTitle" , id ,"newWindow",null,null,null,null,"wframe" );
            };

    scwin.onpageload = function() {

        scwin.createWindowTest("aaa", "windowId0");
    };

    scwin.onpageunload = function() {

    };

	scwin.setVal = function() {
		((j) => j.length ? j : $('#mf_wc1_subWindow0_wframe'))($('#wc1_subWindow0_wframe')).animate({scrollTop:600},0,function(){});
	}    
	scwin.checkVal = function() {
		return scwin.__getJq('#wc1_subWindow0_wframe_'+$p.id+'wc1_subWindow0_wframe_wq_processMsgComp').offset().top < 300;
	}
